//! T3 Code's theme palettes, ported from `packages/shared/src/themePalettes.ts` and
//! `apps/web/src/themePalette.ts`. Every color is the 8-bit sRGB the web client paints.
//!
//! Built-ins come from `assets/builtin-themes.json`, generated by
//! `apps/rune/scripts/export-builtin-themes.ts`. Environment themes are derived here.

mod color;
mod environment;
mod resolve;
mod vivid;

use std::collections::HashMap;
use std::sync::OnceLock;

pub use color::parse_css_color;
pub use environment::environment_theme;
pub use resolve::{
    AppearanceMode, Halves, ResolvedTheme, ThemePreference, resolve, theme_definition,
};
pub use vivid::vivid_theme_colors;

/// Gamma-encoded sRGB with straight alpha, each channel 0..1.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Srgb {
    pub r: f32,
    pub g: f32,
    pub b: f32,
    pub a: f32,
}

impl Srgb {
    pub fn to_rgba8(self) -> [u8; 4] {
        [self.r, self.g, self.b, self.a].map(|c| (c.clamp(0.0, 1.0) * 255.0).round() as u8)
    }

    /// `#rrggbb`, or `#rrggbbaa` when not opaque, as `themeColorToHex` writes it.
    pub fn to_hex(self) -> String {
        let [r, g, b, a] = self.to_rgba8();
        if a == 255 {
            format!("#{r:02x}{g:02x}{b:02x}")
        } else {
            format!("#{r:02x}{g:02x}{b:02x}{a:02x}")
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Appearance {
    Light,
    Dark,
}

impl Appearance {
    pub const ALL: [Appearance; 2] = [Appearance::Light, Appearance::Dark];

    pub fn name(self) -> &'static str {
        match self {
            Appearance::Light => "light",
            Appearance::Dark => "dark",
        }
    }

    pub fn from_name(name: &str) -> Option<Appearance> {
        Appearance::ALL.into_iter().find(|a| a.name() == name)
    }
}

macro_rules! roles {
    ($($variant:ident => $name:literal),* $(,)?) => {
        /// `THEME_COLOR_ROLES`, in order; the discriminant indexes [`ThemeColors`].
        #[repr(usize)]
        #[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
        pub enum Role { $($variant),* }

        impl Role {
            pub const ALL: [Role; ROLE_COUNT] = [$(Role::$variant),*];

            /// The camelCase name used on the wire and in theme files.
            pub fn name(self) -> &'static str {
                match self { $(Role::$variant => $name),* }
            }
        }
    };
}

pub const ROLE_COUNT: usize = 61;

