impl Role {
    pub fn from_name(name: &str) -> Option<Role> {
        Role::ALL.into_iter().find(|role| role.name() == name)
    }
}

/// One color per [`Role`], indexed by its discriminant.
#[derive(Clone, Debug, PartialEq)]
pub struct ThemeColors(pub [Srgb; ROLE_COUNT]);

impl ThemeColors {
    pub fn get(&self, role: Role) -> Srgb {
        self.0[role as usize]
    }

    pub fn set(&mut self, role: Role, color: Srgb) {
        self.0[role as usize] = color;
    }
}

/// The palette for the appearance a theme does not natively use.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Variants {
    pub light: Option<ThemeColors>,
    pub dark: Option<ThemeColors>,
}

impl Variants {
    pub fn get(&self, appearance: Appearance) -> Option<&ThemeColors> {
        match appearance {
            Appearance::Light => self.light.as_ref(),
            Appearance::Dark => self.dark.as_ref(),
        }
    }

    fn slot(&mut self, appearance: Appearance) -> &mut Option<ThemeColors> {
        match appearance {
            Appearance::Light => &mut self.light,
            Appearance::Dark => &mut self.dark,
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ThemeSource {
    BuiltIn,
    /// Published by a connected server; see [`environment_theme`].
    Environment,
}

#[derive(Clone, Debug, PartialEq)]
pub struct ThemeDefinition {
    pub id: String,
    pub label: String,
    /// The appearance `colors` paints; `variants` never holds this one.
    pub appearance: Appearance,
    pub colors: ThemeColors,
    pub variants: Variants,
    /// Built-in palettes that keep the sidebar's environment artwork.
    pub sidebar_artwork: bool,
    pub source: ThemeSource,
}

impl ThemeDefinition {
    pub fn colors_for(&self, appearance: Appearance) -> Option<&ThemeColors> {
        if appearance == self.appearance {
            Some(&self.colors)
        } else {
            self.variants.get(appearance)
        }
    }

    /// The appearances this theme can paint, light first.
    pub fn appearances(&self) -> Vec<Appearance> {
        Appearance::ALL
            .into_iter()
            .filter(|&a| self.colors_for(a).is_some())
            .collect()
    }
}

struct Builtins {
    themes: Vec<ThemeDefinition>,
    standard_light: ThemeColors,
    standard_dark: ThemeColors,
}

#[derive(serde::Deserialize)]
struct Asset {
    standard: HashMap<String, HashMap<String, String>>,
    themes: Vec<AssetTheme>,
}

#[derive(serde::Deserialize)]
#[serde(rename_all = "camelCase")]
struct AssetTheme {
    id: String,
    label: String,
    appearance: String,
    sidebar_artwork: bool,
    colors: HashMap<String, String>,
    variants: HashMap<String, HashMap<String, String>>,
}

fn asset_hex(hex: &str) -> Srgb {
    let digits = hex
        .strip_prefix('#')
        .filter(|d| matches!(d.len(), 6 | 8))
        .expect("asset colors are #rrggbb[aa]");
    let byte =
        |i: usize| u8::from_str_radix(&digits[i..i + 2], 16).expect("asset hex") as f32 / 255.0;
    Srgb {
        r: byte(0),
        g: byte(2),
        b: byte(4),
        a: if digits.len() == 8 { byte(6) } else { 1.0 },
    }
}

fn asset_colors(map: &HashMap<String, String>) -> ThemeColors {
    ThemeColors(
        Role::ALL.map(|role| asset_hex(map.get(role.name()).expect("asset has every role"))),
    )
}

fn builtins() -> &'static Builtins {
    static BUILTINS: OnceLock<Builtins> = OnceLock::new();
    BUILTINS.get_or_init(|| {
        let asset: Asset = serde_json::from_str(include_str!("../assets/builtin-themes.json"))
            .expect("builtin-themes.json");
        let themes = asset
            .themes
            .iter()
            .map(|theme| {
                let mut variants = Variants::default();
                for (appearance, colors) in &theme.variants {
                    *variants.slot(Appearance::from_name(appearance).expect("asset appearance")) =
                        Some(asset_colors(colors));
                }
                ThemeDefinition {
                    id: theme.id.clone(),
                    label: theme.label.clone(),
                    appearance: Appearance::from_name(&theme.appearance).expect("asset appearance"),
                    colors: asset_colors(&theme.colors),
                    variants,
                    sidebar_artwork: theme.sidebar_artwork,
                    source: ThemeSource::BuiltIn,
                }
            })
            .collect();
        Builtins {
            themes,
            standard_light: asset_colors(&asset.standard["light"]),
            standard_dark: asset_colors(&asset.standard["dark"]),
        }
    })
}

/// T3 Chat, Grove, Ocean, Ember and Iris, in picker order.
pub fn builtin_themes() -> &'static [ThemeDefinition] {
    &builtins().themes
}

/// The stock "T3 Code" theme as the web's index.css paints it.
pub fn standard_colors(appearance: Appearance) -> &'static ThemeColors {
    match appearance {
        Appearance::Light => &builtins().standard_light,
        Appearance::Dark => &builtins().standard_dark,
    }
}

/// The base environment themes build on (`getDefaultThemeColors`): T3 Chat and its dark variant.
pub(crate) fn default_colors(appearance: Appearance) -> &'static ThemeColors {
    let t3_chat = &builtin_themes()[0];
    debug_assert_eq!(t3_chat.id, "t3-chat");
    t3_chat
        .colors_for(appearance)
        .expect("T3 Chat has both appearances")
}
